"use strict";
// N73 layout follows Nokia's front-key guide; click areas are enlarged for touch.
const modelHardwareBase=phoneHardwareMarkup,modelRenderPhoneBase=renderPhoneLab;
phoneHardwareMarkup=function(){if(phoneState.model==='nokia5230')return `<div class="device-controls hardware-5230"><button data-phone-app="contacts" class="key-call" aria-label="5230通话键">☎</button><button data-phone-app="home" aria-label="5230菜单键">▭</button><button data-phone-app="home" class="key-end" aria-label="5230结束键">☎</button></div>`;
 if(phoneState.model!=='n73')return modelHardwareBase();
 return `<div class="device-controls hardware-fiveway hardware-n73"><div class="hardware-side"><button data-phone-soft="left" aria-label="N73左选择键">—</button><button data-phone-app="contacts" class="device-call" aria-label="N73通话键">☎</button></div><div class="device-dpad n73-joystick"><button data-phone-dir="up" aria-label="手机方向上">▲</button><button data-phone-dir="left" aria-label="手机方向左">◀</button><button data-phone-ok aria-label="手机确认">●</button><button data-phone-dir="right" aria-label="手机方向右">▶</button><button data-phone-dir="down" aria-label="手机方向下">▼</button></div><div class="hardware-side"><button data-phone-soft="right" aria-label="N73右选择键">—</button><button data-phone-app="home" class="device-end" aria-label="N73结束键">☎</button></div></div>`;};
renderPhoneLab=function(){const html=modelRenderPhoneBase();if(phoneState.model!=='n73')return html;return html.replace(/(<div class="device-keypad">[\s\S]*?<\/div>)(<button class="device-home-button")/,`<div class="n73-keydeck"><div class="n73-keyrail"><button data-phone-app="home" aria-label="N73菜单键">▦</button><button data-model-edit aria-label="N73编辑键">✎</button></div>$1<div class="n73-keyrail"><button data-phone-app="music" aria-label="N73多媒体键">▧</button><button data-model-clear aria-label="N73清除键">C</button></div></div>$2`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-model-clear],[data-model-edit]');if(!b)return;e.preventDefault();const view=document.querySelector('#device-viewport');const active=document.activeElement;const field=active&&view?.contains(active)&&active.matches('input:not([readonly]),textarea')?active:view?.querySelector('textarea,input:not([readonly]):not([type=file])');if(b.hasAttribute('data-model-edit')){if(field){field.focus();field.select();toast('编辑：已选中当前文本');}else toast('此画面没有可编辑的文本');return;}if(field){const start=field.selectionStart??field.value.length,end=field.selectionEnd??start;field.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();}else if(phoneState.app!=='home')phoneSelectApp('home');});
function syncModelKeys(){document.querySelectorAll('.hardware-n73 [data-phone-soft]').forEach(b=>b.textContent='—');if(typeof tide==='object'&&tide.active&&tide.device==='black'&&tideView!=='deep:download')document.querySelectorAll('.device-softkeys [data-phone-soft]').forEach(b=>b.textContent=b.dataset.phoneSoft==='left'?'选项':'返回');}
const modelRefreshBase=refreshPhone;
refreshPhone=function(){modelRefreshBase();syncModelKeys();if(typeof modelStoryFocus==='number')modelStoryFocus=-1;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-phone-soft]');if(!b||phoneState.model!=='n73'||!tide.active||visitMode==='pc'||tideView==='deep:download'||['java','games','snake'].includes(phoneState.app))return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.phoneSoft==='left'){dialog('N73 / 选项',`${tideBtn('journal','打开随手记')}${deepLink('deep:history','浏览记录')}<button data-phone-app="home">功能表</button><button data-phone-app="music">多媒体</button>`);return;}if(/^deep(photo|back|meta):/.test(tideView))return deepSetView('photos');if(/^photo:|^back:|^meta:/.test(tideView)){tideView='';phoneState.app='photos';return refreshPhone();}if(/^smsdeep:/.test(tideView))return deepSetView('sms');if(tideView==='shop:qq')return deepSetView('qq');if(['shop:message','shop:photo-message','shop:dawn','shop:repair-sms'].includes(tideView)){tideView='sms';phoneState.app='sms';return refreshPhone();}if(/^qq:/.test(tideView))return deepSetView('qq');if(/^forumdeep:/.test(tideView))return deepSetView('deep:forum');if(/^page:/.test(tideView))return deepSetView('deep:history');phoneSelectApp('home');},true);

document.addEventListener('click',e=>{if(e.target.closest('#modal')&&e.target.closest('[data-tide-view],[data-phone-app]'))document.querySelector('#modal')?.close();},true);
let modelStoryFocus=-1;
document.addEventListener('click',e=>{const b=e.target.closest('[data-phone-dir],[data-phone-ok]');if(!b||phoneState.model!=='n73'||!tide.active||visitMode==='pc'||['home','java','snake','arcade'].includes(phoneState.app)||tideView==='deep:download')return;e.preventDefault();e.stopImmediatePropagation();const view=document.querySelector('#device-viewport'),items=Array.from(view?.querySelectorAll('button:not(:disabled),a,summary,input:not([readonly]),textarea,select')||[]);if(!items.length)return;if(b.dataset.phoneDir){const zoom=view.querySelector('.tide-photo.zoomed,.deep-photo.zoomed');if(zoom&&['left','right'].includes(b.dataset.phoneDir)){zoom.scrollBy({left:b.dataset.phoneDir==='left'?-150:150});return;}modelStoryFocus=Math.max(0,Math.min(items.length-1,modelStoryFocus+(['up','left'].includes(b.dataset.phoneDir)?-1:1)));items.forEach((el,i)=>el.classList.toggle('hardware-selected',i===modelStoryFocus));items[modelStoryFocus].scrollIntoView({block:'nearest'});return;}const selected=items.find(el=>el.classList.contains('hardware-selected'))||items[0];if(selected.matches('input,textarea,select'))selected.focus();else selected.click();},true);
